ST.xhtml:
IF error_in AND state <> 3 THEN
    state := 3;                          // ERROR forced from any state
ELSIF state = 0 THEN                     // PAUSE
    IF s1_start THEN
        state := 1;
    ELSIF s4_reset THEN
        state := 2;
    END_IF;
ELSIF state = 1 THEN                     // RUN
    IF s2_stop THEN state := 0; END_IF;  // S4 ignored here
ELSIF state = 2 THEN                     // RESET
    IF s2_stop OR reset_done THEN state := 0; END_IF;   // S1 ignored here
ELSIF state = 3 THEN                     // ERROR
    IF s4_reset THEN state := 2; END_IF; // clears fault, begins reset/homing
END_IF;

run_mode    := (state = 1);
pause_mode  := (state = 0);
reset_mode  := (state = 2);
error_mode  := (state = 3);
start_light := run_mode;
reset_light := reset_mode;

CASE state OF
0:  (* AT_HOME *)
    IF error_mode THEN state := 4;
    ELSIF reset_mode THEN
        IF NOT sensor_home THEN state := 3; END_IF;
    ELSIF run_mode AND go THEN
        state := 1;
    END_IF;
1:  (* TO_END *)
    IF error_mode THEN state := 4;
    ELSIF reset_mode THEN state := 3;          // abort stroke, go home
    ELSIF pause_mode THEN ;                     // freeze in place
    ELSIF sensor_end THEN state := 2;
    END_IF;
2:  (* AT_END *)
    IF error_mode THEN state := 4;
    ELSIF reset_mode THEN state := 3;
    ELSIF run_mode AND go THEN state := 3;      // continuous cycle
    END_IF;
3:  (* TO_HOME *)
    IF error_mode THEN state := 4;
    ELSIF pause_mode AND NOT reset_mode THEN ;  // freeze (reset overrides pause)
    ELSIF sensor_home THEN state := 0;
    END_IF;
4:  (* ERROR -- valves off, recover only via reset sequence *)
    IF reset_mode THEN
        IF sensor_home THEN state := 0; ELSE state := 3; END_IF;
    END_IF;
END_CASE;

// Valves derive from the final state; pause zeroes them (hold in place).
valve_to_end  := (state = 1) AND NOT pause_mode;
valve_to_home := (state = 3) AND NOT pause_mode;

// Stall detection: commanding a valve but not arriving.
moving := valve_to_end OR valve_to_home;
stall(IN := robust AND moving, PT := t_stall);
IF stall.Q THEN state := 4; END_IF;

IF state = 4 THEN
    valve_to_end := FALSE;
    valve_to_home := FALSE;
END_IF;

at_home := (state = 0);
to_end  := (state = 1);
at_end  := (state = 2);
to_home := (state = 3);
error   := (state = 4);

CASE state OF
0:  (* AT_HOME *)
    IF error_mode THEN state := 4;
    ELSIF reset_mode THEN
        IF NOT sensor_home THEN state := 3; END_IF;
    ELSIF run_mode AND go THEN state := 1;
    END_IF;
1:  (* TO_END -- no sensor, trust the stroke timer *)
    IF error_mode THEN state := 4;
    ELSIF strokeT.Q THEN state := 2;
    END_IF;
2:  (* AT_END *)
    IF error_mode THEN state := 4;
    ELSIF reset_mode THEN state := 3;
    ELSIF run_mode THEN state := 3;
    END_IF;
3:  (* TO_HOME -- retract, sensor_home ends it *)
    IF error_mode THEN state := 4;
    ELSIF sensor_home THEN state := 0;
    END_IF;
4:  (* ERROR *)
    IF reset_mode THEN
        IF sensor_home THEN state := 0; ELSE state := 3; END_IF;
    END_IF;
END_CASE;

valve_extend := (state = 1) OR (state = 2);
IF state = 4 THEN valve_extend := FALSE; END_IF;

strokeT(IN := (state = 1), PT := t_stroke);
stallT (IN := robust AND (state = 3), PT := t_stall);   // retract-only stall
IF stallT.Q THEN
    state := 4;
    valve_extend := FALSE;
END_IF;

at_home := (state = 0);
to_end  := (state = 1);
at_end  := (state = 2);
to_home := (state = 3);
error   := (state = 4);

reset_done := Lift.at_home AND Ejector.at_home;
Panel(s1_start := Panel_S1, s2_stop := Panel_S2, s4_reset := Panel_S4,
      error_in := fault, reset_done := reset_done);

IF Panel.reset_mode OR Panel.error_mode THEN
    ps := 0; beam_ctr := 0; proc_fault := FALSE; dest_bottom := FALSE;
END_IF;

beam_blocked := NOT Station_B4;
beam_fault := FALSE;
IF beam_blocked AND (ps = 1 OR ps = 5) THEN
    beam_ctr := beam_ctr + 1;
    IF ROBUST AND beam_ctr >= BEAM_LIMIT THEN beam_fault := TRUE; END_IF;
ELSIF NOT beam_blocked THEN
    beam_ctr := 0;
END_IF;

go_lift := FALSE; go_ej := FALSE; blower := FALSE;
IF Panel.run_mode THEN
    CASE ps OF
    0:  (* IDLE: latch class of the presented workpiece *)
        IF Part_AV THEN
            black := NOT Station_B2;
            IF black THEN ps := 4;              // straight to bottom, no lift
            ELSE ps := 1; END_IF;
        END_IF;
    1:  (* LIFTING to the height sensor *)
        IF NOT beam_blocked THEN
            go_lift := TRUE;
            IF Lift.at_end THEN ps := 2; END_IF;
        END_IF;
    2:  (* HEIGHT decision *)
        tall := Station_B5;
        IF tall THEN                            // red / metal -> top slide
            IF top < CAP THEN ps := 3; ELSE ps := 5; dest_bottom := FALSE; END_IF;
        ELSE                                    // white -> bottom slide
            IF ROBUST AND bottom >= CAP THEN
                proc_fault := TRUE;             // bottom full: stop at entry, error
            ELSE
                dest_bottom := TRUE; ps := 5;
            END_IF;
        END_IF;
    3:  (* EJECT to TOP slide, blower on *)
        go_ej := TRUE; blower := TRUE;
        IF Ejector.at_end THEN top := top + 1; dest_bottom := FALSE; ps := 5; END_IF;
    4:  (* EJECT to BOTTOM slide *)
        go_ej := TRUE;
        IF Ejector.at_end THEN bottom := bottom + 1; ps := 0; END_IF;
    5:  (* LOWER lift home, then dispatch *)
        go_lift := TRUE;
        IF Lift.at_home THEN
            IF dest_bottom THEN ps := 4; ELSE ps := 0; END_IF;
        END_IF;
    END_CASE;
END_IF;

Lift(run_mode := Panel.run_mode, pause_mode := Panel.pause_mode,
    reset_mode := Panel.reset_mode, error_mode := Panel.error_mode,
    sensor_home := Station_1B2, sensor_end := Station_1B1, go := go_lift,
    t_stall := T#2s, robust := ROBUST);

Ejector(run_mode := Panel.run_mode, pause_mode := Panel.pause_mode,
    reset_mode := Panel.reset_mode, error_mode := Panel.error_mode,
    sensor_home := Station_2B1, go := go_ej,
    t_stroke := T#1s, t_stall := T#2s, robust := ROBUST);

fault := ROBUST AND (Lift.error OR Ejector.error OR beam_fault OR proc_fault);

// ---- physical outputs ----
Station_1Y1 := Lift.valve_to_home;     // Lift Down
Station_1Y2 := Lift.valve_to_end;      // Lift Up
Station_2Y1 := Ejector.valve_extend;   // Advance Ejecting Cylinder
Station_3Y1 := blower AND NOT Panel.error_mode;  // Air Cushion (blower, ~1 s)
Station_H1  := Panel.start_light;
Station_H2  := Panel.reset_light;
Station_H3  := (bottom >= CAP);        // Q1  bottom slide full
Station_H4  := Panel.error_mode;       // Q2
IP_N_FO     := Panel.run_mode;         // station occupied (integrated line)
